"""Phase 2 report: tables + mechanical application of the frozen criteria in docs/phase2_plan.md (no thresholds are chosen here)."""
import json
from pathlib import Path

import numpy as np
from scipy import stats

R = Path(__file__).resolve().parents[1] / "results/phase2"
md, crit = [], {}
ml = md.append
S1 = json.load(open(R / "stage1.json")); KS = [1, 2, 4, 8, 16, 32, 64]; K8 = KS.index(8)
GATE = json.load(open(R / "recompute_gate.json")); CTX = json.load(open(R / "recompute_gate_context.json")) if (R / "recompute_gate_context.json").exists() else None
ml("# Phase 2 report tables (auto-generated by scripts/phase2_report.py)\n")
ml("## Recompute gate (hard gate for routing/content and A/V patching)\n")
ml("| layer | layer rel. L2 | median head rel. L2 | max head rel. L2 | d_c-contribution error (max / std) | row-sum dev |\n|---|---|---|---|---|---|")
for l, v in GATE["layers"].items():
    ml(f"| {l} | {v['layer_rel_L2']:.4f} | {v['median_head_rel_L2']:.4f} | {v['max_head_rel_L2']:.4f} | {v['dc_contribution_err_over_std']:.4f} | {v['attention_row_sum_max_dev']:.1e} |")
ml(f"\nGate verdict: **{'PASS' if GATE['pass'] else 'FAIL'}** (criterion for the d_c contribution is the worst-case error over all real positions and heads ≤ 2 % of std). Self-patch noise on answer margins: {GATE['self_patch_margin_noise']}. Eager-vs-sdpa: {json.dumps(GATE['eager'])[:600]}.")
if CTX:
    ml("\nSupplementary context (does not change the verdict): " + "; ".join(f"layer {l}: RMS {v['all_positions']['rms_over_std']:.4f}, p99 {v['all_positions']['p99_over_std']:.4f}, max {v['all_positions']['max_over_std']:.4f} (last position max {v['last_position']['max_over_std']:.4f}) of std" for l, v in CTX.items()))
crit["recompute_gate_passed"] = bool(GATE["pass"])

# ---------------------------------------------------------------- Stage 1
nl = S1["native_logic"]
ml("\n## Stage 1 — head decomposition (training prompts; held-out confirmation)\n")
ml(f"Net attention class difference (logic): train {nl['total_signed']:+.2f} (held-out {nl['held_out_total_signed']:+.2f}); Σ|Δ_h| = {nl['total_abs']:.2f}; κ = {nl['kappa']:.2f}; identity ok: {S1['identity_ok']}; gate S1: {S1['gate_S1']}.")
ml("\nSelected sets (frozen, pooled top-k by training |Δ_h|): S8 = " + ", ".join(f"L{s['layer']}H{s['head']} ({s['delta']:+.2f})" for s in S1["selection"]["S8"]) + f"; S8 holds {S1['selection']['coverage_S8_of_total_abs']:.3f} of Σ|Δ| and {S1['selection']['coverage_S8_signed_of_net']:.3f} of the signed net.")
ml("\nPer layer (logic): signed / abs mass: " + ", ".join(f"L{l}: {nl['layer_signed'][l]:+.2f}/{nl['layer_abs_mass'][l]:.2f}" for l in range(16, 23)))
ml("\n| analysis | native top-1/2/4/8/16/32/64 share (pooled) | N_eff | Gini | within-layer top-2 (19–22, mass-wtd) | within-layer N_eff |\n|---|---|---|---|---|---|")
for a, v in S1["concentration"].items():
    n = v["native"]; ml(f"| {a} | {' / '.join(f'{x[0]:.3f}' for x in n['pooled']['topk'])} | {n['pooled']['n_eff'][0]:.1f} | {n['pooled']['gini'][0]:.3f} | {n['within']['top2'][0]:.3f} | {n['within']['n_eff'][0]:.2f} |")
ml("\nNulls for cons/logic (layer-mass-matched pooled; these are alternative coordinate decompositions of the same update, **not heads**):\n")
ml("| family | n | top-8 share mean [max] | ratio native/mean | native above all draws | N_eff mean | N_eff ratio | within-layer top-2 | within-layer N_eff |\n|---|---|---|---|---|---|---|---|---|")
v = S1["concentration"]["cons/logic"]; nat8 = v["native"]["pooled"]["topk"][K8][0]; natne = v["native"]["pooled"]["n_eff"][0]
geo = {}
for f, nu in v["nulls"].items():
    t = np.array(nu["pooled_layer_matched"]["topk"][K8]); ne = np.array(nu["pooled_layer_matched"]["n_eff"])
    geo[f] = dict(ratio=nat8 / t.mean(), above_all=bool(nat8 > t.max()), neff_ratio=natne / ne.mean())
    ml(f"| {f} | {nu['n']} | {t.mean():.3f} [{t.max():.3f}] | {nat8 / t.mean():.2f} | {nat8 > t.max()} | {ne.mean():.1f} | {natne / ne.mean():.3f} | {np.mean(nu['within']['top2']):.3f} | {np.mean(nu['within']['n_eff']):.2f} |")
ml(f"\nNative: top-8 {nat8:.3f}, N_eff {natne:.1f}, within-layer top-2 {v['native']['within']['top2'][0]:.3f}. Subsets (layer-matched, true-Haar blocks): " + "; ".join(f"{k}: native top-8 {s['native']['topk'][K8][0]:.3f} vs null {np.mean(s['haar_block_true']['topk'][K8]):.3f}" for k, s in v["subsets"].items()) + f". Sampler validation: {S1['sampler_validation']}.")
rec = S1["reconstruction"]
ml("\n| k heads | native signed frac of held-out net | native per-example R² | random-k frac mean [max] (n=100) | Haar-rotated-block frac mean [max] (n=10) | Haar-block R² |\n|---|---|---|---|---|---|")
for k in map(str, KS):
    n, r, h = rec["native"][k], rec["random"][k], rec["haar_block"][k]
    ml(f"| {k} | {n['frac']:+.3f} | {n['r2']:.3f} | {r['frac_mean']:+.3f} [{r['frac_max']:+.3f}] | {h['frac_mean']:+.3f} [{h['frac_max']:+.3f}] | {h['r2_mean']:.3f} |")
ml(f"\nCancellation (logic held-out): κ = {rec['cancellation_test']['kappa']:.2f} (pos {rec['cancellation_test']['pos_mass']:.2f}, neg {rec['cancellation_test']['neg_mass']:.2f}); per layer {({l: round(c['kappa'], 2) for l, c in rec['per_layer_cancellation_test'].items()})}; mean per-example κ_i {rec['mean_per_example_kappa_test']:.1f}. Note: a random 8-head set contains the dominant head L22H5 in about 1 % of draws, which explains the large 'max' column entries.")
ml(f"\nSplit-half: {S1['split_half']}. Held-out confirmation of training top-8: {S1['heldout_confirmation']}.")
ml("\nCross-task (head |Δ| rankings):\n\n| pair | Spearman signed | Spearman |Δ| | held-out signed | top-8 overlap (expected) | top-16 overlap (expected) |\n|---|---|---|---|---|---|")
for k, c in S1["cross_task"].items():
    ml(f"| {k} | {c['spearman_signed']:.3f} | {c['spearman_abs']:.3f} | {c['heldout_spearman_signed']:.3f} | {c['top8']['overlap']} ({c['top8']['expected']:.2f}) | {c['top16']['overlap']} ({c['top16']['expected']:.2f}) |")
t8 = v["nulls"]["haar_block_true"]; pm = v["nulls"]["permuted_block"]
Ga = (nat8 >= 2 * np.mean(t8["pooled_layer_matched"]["topk"][K8]) and geo["haar_block_true"]["above_all"] and geo["haar_block_true"]["neff_ratio"] <= 0.5
      and nat8 >= 2 * np.mean(pm["pooled_layer_matched"]["topk"][K8]) and geo["permuted_block"]["above_all"] and geo["permuted_block"]["neff_ratio"] <= 0.5)
Gb = rec["native"]["8"]["frac"] >= 0.5 and rec["native"]["8"]["r2"] >= 0.5 and rec["random"]["8"]["frac_mean"] < 0.10
crit["H_geometric"] = dict(concentration_vs_haar_and_permuted_blocks=bool(Ga), reconstruction=bool(Gb), passed=bool(Ga and Gb),
                           vs_head_shuffled_alignment_context=dict(ratio=geo["head_shuffled"]["ratio"], above_all=geo["head_shuffled"]["above_all"]))

# ---------------------------------------------------------------- Stage 3
z = np.load(R / "stage3/conditions.npz", allow_pickle=True); ST = {k: z[k] for k in z.files}
mt = np.load(R / "stage3/eval_meta.npz"); GR, AC = mt["groups"], mt["accept"]
names = sorted({k.split("||")[0] for k in ST if k.endswith("||margin")})
M = lambda n: ST[f"{n}||margin"]
MIN_DEN = 10.0
def gap(n, g, rows=None):
    m_, a_ = M(n)[GR == g], AC[GR == g]
    if rows is not None: m_, a_ = m_[rows], a_[rows]
    return float(m_[a_].mean() - m_[~a_].mean())
def Rraw(n, g, rows=None): return gap("intact", g, rows) - gap(n, g, rows)
def Eg(n, g, rows=None, den_min=MIN_DEN):
    d = Rraw("dc_ablation", g, rows); return Rraw(n, g, rows) / d if d >= den_min else float("nan")
def shift(n, g): return float(M(n)[GR == g].mean() - M("intact")[GR == g].mean())
def cgap(n, g="logic_num_orig"): c_, a_ = ST[f"{n}||c"][GR == g], AC[GR == g]; return float(c_[a_].mean() - c_[~a_].mean())
def dgap(n, g="logic_num_orig"):
    d_, a_ = ST[f"{n}||direct"][GR == g], AC[GR == g]; return float(d_[a_].mean() - d_[~a_].mean()) if not np.all(np.isnan(d_)) else float("nan")
def auc(n, g):
    m_, a_ = M(n)[GR == g], AC[GR == g]; r = stats.rankdata(m_); n1 = a_.sum(); return float((r[a_].sum() - n1 * (n1 + 1) / 2) / (n1 * (~a_).sum()))
def Pn(n): return float(ST[f"{n}||dh"][GR == "logic_num_orig"].mean())
TASKS = ["logic_num_orig", "logic_num_rev", "localizer", "prontoqa"]
ml("\n## Stage 3 — head ablations on the confirmatory set (mean replacement, all positions unless stated)\n")
ml("Raw margin class gaps (logits), intact: " + ", ".join(f"{g}: {gap('intact', g):.1f}" for g in np.unique(GR)) + "; after d_c ablation: " + ", ".join(f"{g}: {gap('dc_ablation', g):.1f}" for g in TASKS) +
   f". **Raw reduction R_T(dc)**: " + ", ".join(f"{g}: {Rraw('dc_ablation', g):.1f}" for g in TASKS) + f". E_gap is undefined unless R_T(dc) ≥ {MIN_DEN:.0f} logits (PrOntoQA is therefore reported through raw reductions only).\n")
ml("| condition | raw ΔGap logic num_orig | E_gap logic num_orig | E_gap logic num_rev | E_gap localizer | raw ΔGap PrOntoQA | shift logic num_orig | AUC logic num_orig (intact %.3f) | verdict-coordinate class gap at hook (intact %.1f) | direct class-gap change | mean ‖Δh‖ | KL | verdict-free shifts MMLU / Stroop / word recall |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|" % (auc("intact", "logic_num_orig"), cgap("intact")))
def row(n, label=None):
    ml(f"| {label or n} | {Rraw(n, 'logic_num_orig'):.2f} | {Eg(n, 'logic_num_orig'):.3f} | {Eg(n, 'logic_num_rev'):.3f} | {Eg(n, 'localizer'):.3f} | {Rraw(n, 'prontoqa'):.2f} | {shift(n, 'logic_num_orig'):+.1f} | {auc(n, 'logic_num_orig'):.3f} | {cgap(n):.1f} | {dgap(n):+.2f} | {Pn(n):.1f} | {float(ST[n + '||kl']):.3f} | {shift(n, 'mmlu_binary'):+.2f} / {shift(n, 'stroop'):+.2f} / {shift(n, 'word_recall_48'):+.2f} |")
row("dc_ablation", "d_c ablation (reference)")
for k in (1, 2, 4):
    row(f"native|k={k}|rank=abs|mean|all", f"top-{k} heads (|Δ| ranking)")
row("native|S8|mean|all", "**S8** (primary)"); row("native|S16|mean|all", "S16")
for k in (32, 64): row(f"native|k={k}|rank=abs|mean|all", f"top-{k} heads")
for n_, lab in (("native|S8|mean|last", "S8, last position only"), ("native|S8|zero|all", "S8, zero replacement"), ("native|S8|resample|all", "S8, resample replacement"),
                ("native|S16|mean|last", "S16, last position only"), ("native|S16|zero|all", "S16, zero"), ("native|S16|resample|all", "S16, resample")):
    row(n_, lab)
ml("\nAlternative rankings (k = 8 and 16):\n"); ml(md[-1] if False else "| condition | raw ΔGap logic num_orig | E_gap logic num_orig | E_gap logic num_rev | E_gap localizer | raw ΔGap PrOntoQA | shift logic num_orig | AUC | coordinate gap | direct | ‖Δh‖ | KL | verdict-free |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for rk in ("abs", "signed", "magnitude", "localizer", "prontoqa"):
    for k in (8, 16):
        n_ = "native|S8|mean|all" if (rk == "abs" and k == 8) else "native|S16|mean|all" if (rk == "abs" and k == 16) else f"native|k={k}|rank={rk}|mean|all"
        if n_ in names: row(n_, f"rank={rk}, k={k}")

# controls -------------------------------------------------------------------------------------------------------------------------------------------
FAM = ["random", "layer_restricted", "magnitude_matched", "alignment_matched"]
fam8 = {f: [n for n in names if n.startswith(f"{f}|k=8|")] for f in FAM}
ml("\n### Controls at k = 8 (30 draws per family): E_gap mean [min, max]; exact empirical resolution p_min = 1/31 = 0.032 (not significance); Holm-corrected z-tests over 8 comparisons; paired bootstrap CI of E_native − mean(E_control)\n")
ml("| family | n | " + " | ".join(["logic_num_orig", "logic_num_rev", "localizer"]) + " | mean ‖Δh‖ | max KL | max verdict-free |shift| |\n|---|---|---|---|---|---|---|---|")
rng = np.random.default_rng(0)
comps, ctab = [], {}
for f in FAM:
    cs = fam8[f]
    if not cs: continue
    cells = []
    for g in ("logic_num_orig", "logic_num_rev", "localizer"):
        e = np.array([Eg(c, g) for c in cs]); en = Eg("native|S8|mean|all", g)
        z_ = (en - e.mean()) / e.std(ddof=1); p = float(stats.norm.sf(z_)); sh = stats.shapiro(e).pvalue if len(e) >= 8 else float("nan")
        ng = int((GR == g).sum()); diffs = []
        for _ in range(300):
            rows = rng.integers(0, ng, ng); diffs.append(Eg("native|S8|mean|all", g, rows) - np.mean([Eg(c, g, rows) for c in cs]))
        lo, hi = np.nanquantile(diffs, [.025, .975])
        ctab[(f, g)] = dict(z=float(z_), p_norm=p, shapiro_p=float(sh), above_all=bool(en > e.max()), ci=(float(lo), float(hi)), mean=float(e.mean()), mx=float(e.max()), mn=float(e.min()))
        comps.append((f, g)); cells.append(f"{e.mean():.3f} [{e.min():.3f}, {e.max():.3f}]; z={z_:.1f}; CI[{lo:+.2f},{hi:+.2f}]")
    ml(f"| {f} | {len(cs)} | " + " | ".join(cells) + f" | {np.mean([Pn(c) for c in cs]):.1f} | {max(float(ST[c + '||kl']) for c in cs):.3f} | {max(max(abs(shift(c, x)) for x in ('mmlu_binary', 'stroop', 'word_recall_48')) for c in cs):.2f} |")
# Holm over the comparisons (logic num_orig and num_rev only are primary: 4 families x 2 formats)
prim = [(f, g) for f in FAM for g in ("logic_num_orig", "logic_num_rev") if (f, g) in ctab]
order = sorted(prim, key=lambda k: ctab[k]["p_norm"]); holm_ok = True; m_ = len(order)
for i, k in enumerate(order):
    adj = min(1.0, ctab[k]["p_norm"] * (m_ - i)); ctab[k]["p_holm"] = adj
    holm_ok = holm_ok and adj < 0.05
ml("\nHolm-adjusted one-sided p-values (normal approximation of the control distribution; Shapiro p in brackets): " + "; ".join(f"{f}/{g}: {ctab[(f, g)]['p_holm']:.2g} [{ctab[(f, g)]['shapiro_p']:.2f}]" for f, g in prim) + ".")
ml("\n### Dose–response and k-grid controls (E_gap logic num_orig mean [min, max] over draws)\n\n| k | native | random | layer_restricted | magnitude_matched |\n|---|---|---|---|---|")
for k in (2, 4, 8, 16, 32, 64):
    nat = "native|S8|mean|all" if k == 8 else f"native|k={k}|rank=abs|mean|all"
    cells = []
    for f in FAM[:3]:
        cs = [n for n in names if n.startswith(f"{f}|k={k}|")]
        e = [Eg(c, "logic_num_orig") for c in cs]; cells.append(f"{np.mean(e):.3f} [{np.min(e):.3f}, {np.max(e):.3f}] (n={len(e)})" if e else "-")
    if nat in names: ml(f"| {k} | {Eg(nat, 'logic_num_orig'):.3f} | " + " | ".join(cells) + " |")
mp = [(int(n.split("L")[1].split("H")[0]), int(n.split("H")[1]), Eg(n, "logic_num_orig"), Eg(n, "logic_num_rev"), Eg(n, "localizer")) for n in names if n.startswith("map|")]
if mp:
    mp.sort(key=lambda x: -abs(x[2]))
    ml("\n### Single-head ablation map, layers 19–22 (top 12 by |E_gap logic num_orig|; all 128 stored)\n\n| head | E_gap logic num_orig | num_rev | localizer | in S8? | training |Δ_h| rank |\n|---|---|---|---|---|---|")
    rank = {(int(i // 32), int(i % 32)): r for r, i in enumerate(np.argsort(-np.abs(np.load(R / 'stage1_arrays.npz')['delta_logic']).reshape(-1)))}
    s8 = {(s["layer"], s["head"]) for s in S1["selection"]["S8"]}
    for l, h, e1, e2, e3 in mp[:12]: ml(f"| L{l}H{h} | {e1:.3f} | {e2:.3f} | {e3:.3f} | {(l, h) in s8} | {rank[(l, h)] + 1} |")
    ml(f"\nHeads with |E_gap| ≥ 0.05 in the map: {sum(1 for x in mp if abs(x[2]) >= 0.05)} of {len(mp)}; Spearman between training |Δ_h| rank and |single-head effect| over the 128 heads: {stats.spearmanr([-rank[(x[0], x[1])] for x in mp], [abs(x[2]) for x in mp]).correlation:.3f}.")
if (R / "stage3/generation.json").exists():
    gen = json.load(open(R / "stage3/generation.json"))
    ml("\n### Generation checks (8-token greedy continuations on 64 prompts per group; 1-digit multiplication)\n\n| condition | multiplication acc | fraction of continuations identical to intact (logic num_orig / localizer / PrOntoQA / MMLU / Stroop / word recall) | first-token constant-answer fraction (logic num_orig) |\n|---|---|---|---|")
    for nm, g in gen.items():
        idn = {k: np.mean([a == b for a, b in zip(g[k], gen["intact"][k])]) for k in ("logic_num_orig", "localizer", "prontoqa", "mmlu_binary", "stroop", "word_recall_48")}
        const = max(np.mean([x.strip()[:1] == "1" for x in g["logic_num_orig"]]), np.mean([x.strip()[:1] == "2" for x in g["logic_num_orig"]]))
        ml(f"| {nm} | {g['multiplication_acc']:.3f} | " + " / ".join(f"{v:.2f}" for v in idn.values()) + f" | {const:.2f} |")

# Stage 3 criteria
n8 = "native|S8|mean|all"
C1 = Eg(n8, "logic_num_orig") >= 0.20 and Eg(n8, "logic_num_rev") >= 0.20
exceed_all = all(ctab[k]["above_all"] for k in prim); ci_ok = all(ctab[k]["ci"][0] > 0 for k in prim)
beat_mag = Eg(n8, "logic_num_orig") - Eg("native|k=8|rank=magnitude|mean|all", "logic_num_orig") >= 0.10 and Eg(n8, "logic_num_rev") - Eg("native|k=8|rank=magnitude|mean|all", "logic_num_rev") >= 0.10
vf = {x: shift(n8, x) for x in ("mmlu_binary", "stroop", "word_recall_48")}
C3 = float(ST[n8 + "||kl"]) < 0.02 and all(abs(v) < 1.0 for v in vf.values())
C4 = np.sign(dgap(n8)) == np.sign(cgap(n8) - cgap("intact")) and dgap(n8) != 0
crit["H_causal"] = dict(E_gap_logic=[Eg(n8, "logic_num_orig"), Eg(n8, "logic_num_rev")], C1_effect_size=bool(C1), C2a_exceeds_all_draws=bool(exceed_all), C2b_holm_significant=bool(holm_ok), C2c_bootstrap_CI_excludes_0=bool(ci_ok),
                        C2d_beats_magnitude_ranking=bool(beat_mag), C3_side_effects=bool(C3), side_effect_detail=dict(kl=float(ST[n8 + "||kl"]), verdict_free_shifts=vf), C4_direct_actual_same_sign=bool(C4),
                        passed=bool(C1 and exceed_all and holm_ok and ci_ok and beat_mag and C3 and C4))
E64 = Eg("native|k=64|rank=abs|mean|all", "logic_num_orig")
crit["H_distributed_causal_condition"] = bool(Eg(n8, "logic_num_orig") < 0.05 and E64 < 0.10)

# ---------------------------------------------------------------- patching
if (R / "patching/patching.json").exists():
    PJ = json.load(open(R / "patching/patching.json")); ml("\n## Counterfactual patching of head outputs (full-z only; A-only/V-only and routing/content cancelled by the failed recompute gate)\n")
    ml(f"Alignment-validated pairs: {PJ.get('alignment')}.")
    ml("\n| group | coordinates | position | n_diff | margin transfer | flip-to-source (clean trials) | coordinate transfer (after recomputation) | direct transfer (immediate) |\n|---|---|---|---|---|---|---|---|")
    pt = {}
    for gname, gd in PJ["groups"].items():
        for key in ("S8|all", "S8|last", "S16|all", "S16|last", "L22H5|all", "L22H5|last"):
            r = gd["results"].get(key)
            if r and "transfer" in r: ml(f"| {gname} | {key.split('|')[0]} | {key.split('|')[1]} | {r.get('n_diff')} | {r['transfer']:+.3f} | {r.get('flip_to_source', float('nan')):.3f} | {r.get('c_transfer', float('nan')):+.3f} | {r.get('direct_transfer', float('nan')):+.3f} |")
        for fam in ("random", "layer_restricted", "magnitude_matched"):
            for pos in ("all", "last"):
                rs = [v for k, v in gd["results"].items() if k.startswith(f"{fam}|") and k.endswith(f"|{pos}") and "transfer" in v]
                if rs: ml(f"| {gname} | {fam} (n={len(rs)}) | {pos} | - | mean {np.mean([x['transfer'] for x in rs]):+.3f}, max |.| {max(abs(x['transfer']) for x in rs):.3f} | max flip {max(x.get('flip_to_source', 0) for x in rs):.3f} | - | - |")
    lx = PJ["groups"].get("lexctrl_num_orig_aligned")
    if lx:
        ml("\nSame-label lexical controls (aligned pairs; patching must not change the verdict): " + "; ".join(f"{k}: |Δmargin| {v['abs_shift_mean']:.2f}, verdict change {v['verdict_change_rate']:.3f}" for k, v in lx["results"].items() if k.split("|")[0] in ("S8", "S16", "L22H5") and "abs_shift_mean" in v) +
           "; random/matched head sets: mean verdict change " + f"{np.mean([v['verdict_change_rate'] for k, v in lx['results'].items() if k.split('|')[0] in ('random', 'layer_restricted', 'magnitude_matched') and k.endswith('|all') and 'verdict_change_rate' in v]):.3f}")
    g0 = PJ["groups"].get("match_num_orig_aligned", {}).get("results", {})
    if g0.get("S8|all"):
        rnd = [v["transfer"] for k, v in g0.items() if k.endswith("|all") and k.split("|")[0] in FAM and "transfer" in v]
        nv = [PJ["groups"][g]["results"]["S8|last"]["transfer"] for g in ("unmatched_mmlu_binary", "unmatched_stroop", "unmatched_word_recall_48") if g in PJ["groups"]]
        crit["H_patching"] = dict(S8_all_position_transfer=g0["S8|all"]["transfer"], random_heads_max_abs=float(max(abs(x) for x in rnd)) if rnd else None, non_verdict_S8_last_transfer=nv,
                                  passed=bool(g0["S8|all"]["transfer"] >= 0.10 and rnd and max(abs(x) for x in rnd) < 0.02 and all(abs(x) < 0.05 for x in nv)))

# ---------------------------------------------------------------- Stage 4
if (R / "stage4/conditions.npz").exists():
    z4 = np.load(R / "stage4/conditions.npz", allow_pickle=True); S4 = {k: z4[k] for k in z4.files}
    S4.update({k: v for k, v in ST.items() if k.split("||")[0] in ("intact", "dc_ablation")})
    n4 = sorted({k.split("||")[0] for k in S4 if k.endswith("||margin")})
    def g4(n, g, rows=None):
        m_, a_ = S4[n + "||margin"][GR == g], AC[GR == g]
        if rows is not None: m_, a_ = m_[rows], a_[rows]
        return float(m_[a_].mean() - m_[~a_].mean())
    def E4(n, g, rows=None):
        d = g4("intact", g, rows) - g4("dc_ablation", g, rows); return (g4("intact", g, rows) - g4(n, g, rows)) / d if d >= MIN_DEN else float("nan")
    ml("\n## Stage 4 — attention + MLP (same confirmatory examples, same R_T(dc) denominator; E = signed R(x)/R(dc))\n")
    ml("| condition | raw ΔGap logic num_orig | E logic num_orig | E logic num_rev | E localizer | raw ΔGap PrOntoQA | verdict-coordinate class gap at hook (intact %.1f) | KL | mean ‖Δh‖ | verdict-free shifts MMLU / Stroop / word recall |\n|---|---|---|---|---|---|---|---|---|---|" % cgap("intact"))
    def cg4(n, g="logic_num_orig"): c_, a_ = S4[n + "||c"][GR == g], AC[GR == g]; return float(c_[a_].mean() - c_[~a_].mean())
    for n in ["dc_ablation", "attn|k=1", "attn|k=8", "attn|k=16", "mlp|k=64", "mlp|k=512", "combined|L22H5+mlp64", "combined|L22H5+mlp512", "combined|S8+mlp64", "combined|S8+mlp512", "combined|S16+mlp512", "ref|all_heads_19_22", "ref|all_units_19_22", "ref|all_heads+all_units_19_22"]:
        if n not in n4: continue
        sh4 = lambda g: float(S4[n + "||margin"][GR == g].mean() - S4["intact||margin"][GR == g].mean())
        ml(f"| {n} | {g4('intact', 'logic_num_orig') - g4(n, 'logic_num_orig'):.2f} | {E4(n, 'logic_num_orig'):.3f} | {E4(n, 'logic_num_rev'):.3f} | {E4(n, 'localizer'):.3f} | {g4('intact', 'prontoqa') - g4(n, 'prontoqa'):.2f} | {cg4(n) if n != 'dc_ablation' else float('nan'):.1f} | {float(S4[n + '||kl']) if n != 'dc_ablation' else float(ST['dc_ablation||kl']):.3f} | {float(S4[n + '||dh'][GR == 'logic_num_orig'].mean()) if n != 'dc_ablation' else float('nan'):.1f} | {sh4('mmlu_binary'):+.2f} / {sh4('stroop'):+.2f} / {sh4('word_recall_48'):+.2f} |")
    ml("\nGeneric combined controls (E logic num_orig mean [min, max]): " + "; ".join(f"{k}: {np.mean(v):.3f} [{np.min(v):.3f}, {np.max(v):.3f}] (n={len(v)})" for k, v in
       {p: [E4(n, 'logic_num_orig') for n in n4 if n.startswith(p)] for p in ("ctrl_both|random_heads+random_units512", "ctrl_mixed|S8+random_units512", "ctrl_mixed|random_heads+mlp512")}.items() if v))
    ml("\n### Interactions: I = E_comb − E_attn − E_mlp (paired bootstrap over examples, 2000 resamples). Equivalence to additivity requires the 90 % CI inside ±0.10; a 95 % CI containing 0 alone is only 'compatible with additivity, inconclusive'.\n")
    ml("| attention | MLP | task | E_attn | E_mlp | E_comb | I | 95 % CI of I | 90 % CI of I | classification | gap closure |\n|---|---|---|---|---|---|---|---|---|---|---|")
    inter = {}
    for a_, m_, c_ in (("attn|k=8", "mlp|k=512", "combined|S8+mlp512"), ("attn|k=8", "mlp|k=64", "combined|S8+mlp64"), ("attn|k=16", "mlp|k=512", "combined|S16+mlp512"), ("attn|k=1", "mlp|k=512", "combined|L22H5+mlp512"), ("attn|k=1", "mlp|k=64", "combined|L22H5+mlp64")):
        if not all(x in n4 for x in (a_, m_, c_)): continue
        for g in ("logic_num_orig", "logic_num_rev", "localizer"):
            ng = int((GR == g).sum()); rg = np.random.default_rng(1); bs_ = []
            for _ in range(2000):
                rows = rg.integers(0, ng, ng); bs_.append(E4(c_, g, rows) - E4(a_, g, rows) - E4(m_, g, rows))
            bs_ = np.array(bs_); I = E4(c_, g) - E4(a_, g) - E4(m_, g)
            lo95, hi95 = np.nanquantile(bs_, [.025, .975]); lo90, hi90 = np.nanquantile(bs_, [.05, .95])
            cls = ("equivalent to additivity (±0.10)" if (lo90 >= -0.10 and hi90 <= 0.10) else "sub-additive (redundant)" if hi95 < 0 else "super-additive (interactive)" if lo95 > 0 else "compatible with additivity, inconclusive")
            ec = E4(c_, g); clos = "closes (≥0.80)" if ec >= 0.80 else "partial (0.5–0.8)" if ec >= 0.5 else "does not close (<0.5)"
            inter[(a_, m_, g)] = dict(I=float(I), ci95=(float(lo95), float(hi95)), ci90=(float(lo90), float(hi90)), cls=cls, E_comb=float(ec), E_attn=float(E4(a_, g)), E_mlp=float(E4(m_, g)))
            ml(f"| {a_} | {m_} | {g} | {E4(a_, g):.3f} | {E4(m_, g):.3f} | {ec:.3f} | {I:+.3f} | [{lo95:+.3f}, {hi95:+.3f}] | [{lo90:+.3f}, {hi90:+.3f}] | {cls} | {clos} |")
    crit["stage4"] = {f"{k[0]}+{k[1]}/{k[2]}": v for k, v in inter.items()}
md.append("\n## Frozen criteria applied\n")
ml("```json\n" + json.dumps(crit, indent=1, default=lambda o: bool(o) if isinstance(o, (np.bool_,)) else float(o)) + "\n```")
dist = (nat8 < 1.5 * np.mean(v["nulls"]["haar_block_true"]["pooled_layer_matched"]["topk"][K8])) and crit["H_distributed_causal_condition"]
sparse = crit["H_geometric"]["passed"] and crit["H_causal"]["passed"] and crit.get("H_patching", {}).get("passed", False)
overall = "SPARSE head implementation supported" if sparse else ("DISTRIBUTED head implementation supported" if dist else "MIXED / INCONCLUSIVE")
ml(f"\n**Overall (mechanical): {overall}.** (Routing/content: not evaluated — recompute gate failed.)")
(R / "report_tables.md").write_text("\n".join(md)); json.dump(crit, open(R / "criteria_verdicts.json", "w"), indent=1, default=lambda o: bool(o) if isinstance(o, (np.bool_,)) else float(o))
print("\n".join(md[-30:]))
